const LOGO_SRC = "data:image/jpeg;base64,";
const DB_NAME="FuelReceiptsDB", STORE="receipts", DB_VERSION=1;
let db=null, currentId=null, selectedId=null, saveTimer=null;
let settings={auto:true,confirm:true};

const $=id=>document.getElementById(id);
function nowDate(){
 const d=new Date(), dd=String(d.getDate()).padStart(2,"0"), mm=String(d.getMonth()+1).padStart(2,"0"), yy=d.getFullYear();
 return {date:`${dd}-${String(d.toLocaleString("en",{month:"short"}))}-${yy}`, time:d.toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})};
}
function toast(msg){const t=$("toast");t.textContent=msg;t.classList.add("show");clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove("show"),2200)}
function openDB(){
 return new Promise((resolve,reject)=>{
  const req=indexedDB.open(DB_NAME,DB_VERSION);
  req.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains(STORE)){const s=d.createObjectStore(STORE,{keyPath:"id",autoIncrement:true});s.createIndex("updatedAt","updatedAt")}};
  req.onsuccess=e=>{db=e.target.result;resolve(db)};req.onerror=e=>reject(e.target.error);
 });
}
function tx(mode="readonly"){return db.transaction(STORE,mode).objectStore(STORE)}
function allReceipts(){return new Promise((res,rej)=>{const r=tx().getAll();r.onsuccess=()=>res(r.result.sort((a,b)=>b.updatedAt-a.updatedAt));r.onerror=()=>rej(r.error)})}
function getReceipt(id){return new Promise((res,rej)=>{const r=tx().get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function putReceipt(obj){return new Promise((res,rej)=>{const s=tx("readwrite"),r=s.put(obj);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function deleteReceipt(id){return new Promise((res,rej)=>{const r=tx("readwrite").delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}

function receiptDataFromDOM(){
 const get=k=>document.querySelector(`[data-key="${k}"]`)?.innerText.trim()||"";
 return {
  invoice:get("invoice"), receiptType:get("receiptType"), vehicle:get("vehicle"), mobile:get("mobile"),
  date:get("date"), time:get("time"), product:get("product"), rate:get("rate"), qty:get("qty"), amount:get("amount")
 };
}
function makeReceiptHTML(data){
 return `<div class="logo-box"><img src="${LOGO_SRC}" alt="Bharat Petroleum logo"></div>
 <div class="pump" data-key="pump" contenteditable="true">PIT STOP<br>PATLIPUTRA PATNA<br>PIN.800013</div>
 <hr class="divider">
 <div class="row"><span>INV NO.</span><span>:</span><span class="value" data-key="invoice" contenteditable="true">${esc(data.invoice)}</span></div>
 <div class="row"><span>RECEIPT</span><span>:</span><span class="value" data-key="receiptType" contenteditable="true">${esc(data.receiptType)}</span></div>
 <div class="row"><span>VEH NO.</span><span>:</span><span class="value" data-key="vehicle" contenteditable="true">${esc(data.vehicle)}</span></div>
 <div class="row"><span>MOB.NO</span><span>:</span><span class="value" data-key="mobile" contenteditable="true">${esc(data.mobile)}</span></div>
 <hr class="divider">
 <div class="row"><span>Date</span><span>:</span><span class="value" data-key="date" contenteditable="true">${esc(data.date)}</span></div>
 <div class="row"><span>Time</span><span>:</span><span class="value" data-key="time" contenteditable="true">${esc(data.time)}</span></div>
 <div class="row"><span>Product</span><span>:</span><span class="value" data-key="product" contenteditable="true">${esc(data.product)}</span></div>
 <div class="row"><span>Rate</span><span>:</span><span class="value" data-key="rate" contenteditable="true">${esc(data.rate)}</span></div>
 <div class="row"><span>Qty (Ltr)</span><span>:</span><span class="value" data-key="qty" contenteditable="true">${esc(data.qty)}</span></div>
 <div class="row"><span>Amount (₹)</span><span>:</span><span class="value" data-key="amount" contenteditable="true">${esc(data.amount)}</span></div>
 <hr class="divider"><div class="thanks" contenteditable="true" data-key="thanks">Thank You!<br>Visit Again!!</div>`;
}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function defaultData(){
 const n=nowDate();return {invoice:"Jun-273275-ORGNL",receiptType:"Physical Receipt",vehicle:"NotEntered",mobile:"NotEntered",date:n.date,time:n.time,product:"Petrol",rate:"106.69",qty:"1.24",amount:"132.29"};
}
function renderReceipt(data){
 $("receipt").innerHTML=makeReceiptHTML(data);
 $("receipt").querySelectorAll("[contenteditable=true]").forEach(el=>el.addEventListener("input",scheduleAutoSave));
}
async function saveCurrent(manual=false){
 if(!currentId){await createRecord(defaultData());return}
 const old=await getReceipt(currentId); if(!old)return;
 old.html=$("receipt").innerHTML; old.data=receiptDataFromDOM(); old.updatedAt=Date.now();
 await putReceipt(old); setSavedText(old.updatedAt); await refreshStats(); await renderHistory();
 if(manual)toast("Receipt saved");
}
async function createRecord(data,duplicateOf=null){
 const obj={data,html:makeReceiptHTML(data),createdAt:Date.now(),updatedAt:Date.now(),source:duplicateOf||null};
 const id=await putReceipt(obj);currentId=id;renderReceipt(data);setSavedText(obj.updatedAt);await refreshStats();await renderHistory();return id;
}
function setSavedText(ts){$("savedText").textContent="Last saved: "+new Date(ts).toLocaleString();$("saveStatus").textContent="Auto Saved"}
function scheduleAutoSave(){ $("saveStatus").textContent="Saving…"; if(!settings.auto)return; clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCurrent(false),800)}
async function loadRecord(id){
 const r=await getReceipt(id);if(!r)return;
 currentId=id;renderReceipt(r.data || receiptDataFromHTML(r.html));setSavedText(r.updatedAt);selectedId=id;renderHistory();showTab("editor");
}
function receiptDataFromHTML(h){
 const box=document.createElement("div");box.innerHTML=h;const get=k=>box.querySelector(`[data-key="${k}"]`)?.innerText.trim()||"";
 return {invoice:get("invoice"),receiptType:get("receiptType"),vehicle:get("vehicle"),mobile:get("mobile"),date:get("date"),time:get("time"),product:get("product"),rate:get("rate"),qty:get("qty"),amount:get("amount")};
}
async function renderHistory(){
 const all=await allReceipts(), q=$("search").value.trim().toLowerCase();
 const rows=all.filter(r=>{const d=r.data||{};return !q || Object.values(d).join(" ").toLowerCase().includes(q)});
 $("historyCount").textContent=all.length;$("historyList").innerHTML="";
 if(!rows.length){$("historyList").innerHTML='<div class="empty">No receipts found.</div>'}
 rows.forEach(r=>{
  const d=r.data||{};const el=document.createElement("div");el.className="receipt-item"+(r.id===selectedId?" active":"");el.innerHTML=`<div class="receipt-main"><div class="invoice">${esc(d.invoice)}</div><div class="meta">${esc(d.date)} • ${esc(d.time)}</div></div><div><div class="product">${esc(d.product)}</div><div class="amount">₹${esc(d.amount)}</div></div><div>›</div>`;
  el.onclick=()=>selectHistory(r.id);$("historyList").appendChild(el);
 });
 if(selectedId){const exists=all.find(r=>r.id===selectedId);if(exists)showSelected(exists);else{selectedId=null;$("previewCard").innerHTML='<div class="empty">Select a receipt to preview it.</div>'}}
}
async function selectHistory(id){selectedId=id;await renderHistory()}
function showSelected(r){
 $("previewCard").innerHTML=`<div class="receipt">${r.html}</div>`;
 $("previewCard").querySelectorAll("[contenteditable=true]").forEach(e=>e.removeAttribute("contenteditable"));
 const d=r.data||{};$("details").innerHTML=`<div class="mini-title">Receipt Details</div>
 <div class="info-line"><span>Invoice No.</span><span>${esc(d.invoice)}</span></div>
 <div class="info-line"><span>Product</span><span class="green-text">${esc(d.product)}</span></div>
 <div class="info-line"><span>Amount</span><span class="green-text">₹${esc(d.amount)}</span></div>
 <div class="info-line"><span>Date</span><span>${esc(d.date)}</span></div><div class="info-line"><span>Time</span><span>${esc(d.time)}</span></div>`;
}
function showTab(tab){
 document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));
 $("editorView").style.display=tab==="editor"?"block":"none";$("historyView").style.display=tab==="history"?"block":"none";$("settingsView").classList.toggle("active",tab==="settings");$("aboutView").classList.toggle("active",tab==="about");
 if(tab==="history")renderHistory();
}
function openNewModal(){const d=defaultData();$("mInvoice").value="";$("mReceipt").value=d.receiptType;$("mVehicle").value="";$("mMobile").value="";$("mProduct").value=d.product;$("mRate").value=d.rate;$("mQty").value=d.qty;$("mAmount").value=d.amount;$("modalBack").classList.add("show")}
function closeNewModal(){$("modalBack").classList.remove("show")}
async function createFromModal(){
 const d=defaultData();d.invoice=$("mInvoice").value.trim()||"New-Receipt-"+Date.now();d.receiptType=$("mReceipt").value.trim()||"Physical Receipt";d.vehicle=$("mVehicle").value.trim()||"NotEntered";d.mobile=$("mMobile").value.trim()||"NotEntered";d.product=$("mProduct").value;d.rate=$("mRate").value;d.qty=$("mQty").value;d.amount=$("mAmount").value;
 closeNewModal();await createRecord(d);showTab("editor");toast("New receipt created");
}
async function clearCurrent(){
 if(!currentId){renderReceipt(defaultData());return}
 if(settings.confirm&&!confirm("Clear this receipt and start a blank one?"))return;
 const d=defaultData();d.invoice="";d.vehicle="";d.mobile="";d.amount="0.00";d.qty="0.00";renderReceipt(d);scheduleAutoSave();toast("Current receipt cleared");
}
async function duplicateCurrent(){
 await saveCurrent(false);const r=await getReceipt(currentId);if(!r)return;const d={...r.data,invoice:(r.data.invoice||"Receipt")+"-COPY"};await createRecord(d,currentId);toast("Receipt duplicated")
}
async function deleteSelectedReceipt(){
 if(!selectedId)return toast("Select a receipt first");
 if(settings.confirm&&!confirm("Permanently delete this receipt?"))return;
 await deleteReceipt(selectedId);if(currentId===selectedId)currentId=null;selectedId=null;await refreshStats();await renderHistory();toast("Receipt deleted")
}
async function refreshStats(){const all=await allReceipts();$("totalReceipts").textContent=all.length;$("historyCount").textContent=all.length;$("usedSpace").textContent=Math.max(1,Math.round(JSON.stringify(all).length/1024))+" KB"}
function downloadBlob(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJSON(){allReceipts().then(all=>downloadBlob(new Blob([JSON.stringify({app:"Fuel Receipt Manager",version:1,exportedAt:new Date().toISOString(),receipts:all},null,2)],{type:"application/json"}),"fuel_receipts_backup.json"))}
async function importJSON(file){const obj=JSON.parse(await file.text());if(!obj.receipts||!Array.isArray(obj.receipts))throw Error("Invalid backup");for(const r of obj.receipts){const copy={...r};delete copy.id;await putReceipt(copy)}await refreshStats();await renderHistory();toast("Backup restored")}
async function exportPNGForReceipt(r){
 const wrapper=document.createElement("div");wrapper.style.cssText="position:fixed;left:-100000px;top:0;background:#fff;width:560px";const rec=document.createElement("div");rec.className="receipt";rec.innerHTML=r.html;wrapper.appendChild(rec);document.body.appendChild(wrapper);
 const styles=[...document.styleSheets].map(s=>{try{return [...s.cssRules].map(x=>x.cssText).join("\n")}catch(e){return""}}).join("\n");
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="560" height="760"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml"><style>${styles}</style>${rec.outerHTML}</div></foreignObject></svg>`;
 const blob=new Blob([svg],{type:"image/svg+xml;charset=utf-8"});const url=URL.createObjectURL(blob);const im=new Image();
 im.onload=()=>{const c=document.createElement("canvas");c.width=1120;c.height=1520;const ctx=c.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,1120,1520);c.toBlob(b=>{downloadBlob(b,(r.data?.invoice||"receipt")+".png");URL.revokeObjectURL(url);wrapper.remove();},"image/png")};im.onerror=()=>{wrapper.remove();URL.revokeObjectURL(url);toast("PNG export was blocked by this browser; use Print/PDF instead.")};im.src=url;
}
async function exportCurrentPNG(){await saveCurrent(false);const r=await getReceipt(currentId);if(r)exportPNGForReceipt(r)}
async function printReceipt(r){const old=currentId;renderReceipt(r.data);setTimeout(()=>{window.print();if(old){getReceipt(old).then(x=>renderReceipt(x.data))}},100)}
function toggle(el){el.classList.toggle("on");return el.classList.contains("on")}

$("tabs").addEventListener("click",e=>{const b=e.target.closest(".tab");if(b)showTab(b.dataset.tab)});
$("newBtn").onclick=openNewModal;$("cancelNew").onclick=closeNewModal;$("createNew").onclick=createFromModal;
$("saveBtn").onclick=()=>saveCurrent(true);$("pngBtn").onclick=exportCurrentPNG;$("pdfBtn").onclick=()=>{saveCurrent(false).then(()=>getReceipt(currentId).then(printReceipt))};$("printBtn").onclick=()=>getReceipt(currentId).then(r=>r&&printReceipt(r));$("clearBtn").onclick=clearCurrent;$("duplicateBtn").onclick=duplicateCurrent;
$("search").oninput=renderHistory;$("refreshBtn").onclick=renderHistory;$("editSelected").onclick=()=>selectedId&&loadRecord(selectedId);$("deleteSelected").onclick=deleteSelectedReceipt;
$("pngSelected").onclick=()=>selectedId&&getReceipt(selectedId).then(exportPNGForReceipt);$("pdfSelected").onclick=()=>selectedId&&getReceipt(selectedId).then(printReceipt);
$("autoSwitch").onclick=()=>{settings.auto=toggle($("autoSwitch"));$("autoLabel").textContent=settings.auto?"ON":"OFF";localStorage.setItem("frm_settings",JSON.stringify(settings))};
$("confirmSwitch").onclick=()=>{settings.confirm=toggle($("confirmSwitch"));localStorage.setItem("frm_settings",JSON.stringify(settings))};
$("backupBtn").onclick=exportJSON;$("restoreBtn").onclick=()=>$("restoreFile").click();$("restoreFile").onchange=e=>e.target.files[0]&&importJSON(e.target.files[0]).catch(()=>toast("Invalid backup file"));
$("wipeBtn").onclick=async()=>{if(confirm("Delete ALL saved receipts from this browser?")){const all=await allReceipts();for(const r of all)await deleteReceipt(r.id);currentId=null;selectedId=null;renderReceipt(defaultData());await refreshStats();await renderHistory();toast("Database cleared")}};
$("installBtn").onclick=()=>toast("For a true installable PWA, use the split-file production version with manifest + service worker.");
$("modalBack").onclick=e=>{if(e.target===$("modalBack"))closeNewModal()};

(async()=>{
 try{await openDB();const s=JSON.parse(localStorage.getItem("frm_settings")||"{}");settings={...settings,...s};$("autoSwitch").classList.toggle("on",settings.auto);$("confirmSwitch").classList.toggle("on",settings.confirm);$("autoLabel").textContent=settings.auto?"ON":"OFF";
  const all=await allReceipts();if(all.length){currentId=all[0].id;renderReceipt(all[0].data);setSavedText(all[0].updatedAt);selectedId=all[0].id}else{await createRecord(defaultData())}
  await refreshStats();await renderHistory();
 }catch(e){console.error(e);toast("IndexedDB is unavailable in this browser.")}
})();

// BP fuel calculation helper
window.bpCalculateAmount=function(rate,qty){
 return (Number(rate||0)*Number(qty||0)).toFixed(2);
};


// BP Integrated Receipt v2.2
const BPReceipt={
 generateInvoice:function(){
   const d=new Date();
   return "BP-"+d.getFullYear()+
   String(d.getMonth()+1).padStart(2,"0")+
   String(d.getDate()).padStart(2,"0")+"-"+Date.now().toString().slice(-5);
 },
 calculate:function(rate,litres){
   return Number(rate||0)*Number(litres||0);
 }
};
window.BPReceipt=BPReceipt;
